class NativeAggregatePlaceholderTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void specializedGroupDoesNotRequireRewritingItsUnevaluatedPlaceholder() {
		Group group = new Group(new SingletonSet());
		group.addGroupElement(new GroupElem("total", new Sum(Var.of("amount", VF.createLiteral(99))
				.withApiInputOrigin())));
		LmdbNativeEvaluationStrategy strategy = mock(LmdbNativeEvaluationStrategy.class);
		QueryEvaluationStep child = mock(QueryEvaluationStep.class);
		for (String target : List.of("total", "unassigned")) {
			Sum placeholder = new Sum(Var.of("amount"));
			Extension extension = new Extension(group.clone(), new ExtensionElem(placeholder, target));
			assertThat(NativeBindingSetExtensionStep.tryCreate(child, extension, group, strategy, context()))
					.as("unevaluated placeholder target=%s", target)
					.isSameAs(child);
			assertThat(((Var) placeholder.getArg()).hasValue()).isFalse();
		}
		verifyNoInteractions(strategy);
	}

	@Test
	void rowCopiesSkipPlaceholdersWithoutAssigningTheirTargets() {
		LmdbNativeAggregatePlanner planner = planner();
		Extension extension = new Extension(new SingletonSet(),
				new ExtensionElem(new Count(Var.of("unread")), "amount"),
				new ExtensionElem(Var.of("amount"), "copied"));
		CopyBinding[] copies = planner.compileExtensionCopies(extension);
		assertThat(copies).hasSize(1);
		assertThat(copies[0].sourceSlot).isEqualTo(planner.slot("amount"));
		assertThat(copies[0].targetSlot).isEqualTo(planner.slot("copied"));
		assertThat(planner.layout.slot("unread")).isNull();
		assertThat(planner.compileExtensionCopies(new Extension(new SingletonSet(),
				new ExtensionElem(new Count(Var.of("unread")), "unassigned")))).isEmpty();
		assertThat(planner.layout.slot("unassigned")).isNull();
	}

	@Test
	void aggregateInsideAnEvaluatedExpressionIsNotAPlaceholder() {
		ValueExpr expression = new MathExpr(new Count(Var.of("amount")),
				new ValueConstant(VF.createLiteral(1)), MathOp.PLUS);
		Extension extension = new Extension(new SingletonSet(), new ExtensionElem(expression, "total"));
		assertThat(planner().compileExtensionCopies(extension)).isNull();
		LmdbNativeEvaluationStrategy strategy = mock(LmdbNativeEvaluationStrategy.class);
		when(strategy.precompile(same(expression), any(QueryEvaluationContext.class)))
				.thenThrow(new QueryEvaluationException("evaluated-nested-aggregate"));
		assertThatThrownBy(() -> NativeBindingSetExtensionStep.tryCreate(mock(QueryEvaluationStep.class), extension,
				null, strategy, context())).isInstanceOf(QueryEvaluationException.class)
						.hasMessage("evaluated-nested-aggregate");
	}

	@Test
	void specializedGroupKeepsItsAuthoritativeLengthDemand() {
		Group group = new Group(new SingletonSet());
		GroupConcat executed = new GroupConcat(Var.of("amount", VF.createLiteral("😀"))
				.withApiInputOrigin());
		executed.setSeparator(new ValueConstant(VF.createLiteral("|")));
		GroupElem definition = new GroupElem("cat", executed);
		group.addGroupElement(definition);
		GroupConcat placeholder = new GroupConcat(Var.of("amount"));
		placeholder.setSeparator(Var.of("separator"));
		Extension aggregate = new Extension(group, new ExtensionElem(placeholder, "cat"));
		Extension length = new Extension(aggregate,
				new ExtensionElem(new FunctionCall(FN.STRING_LENGTH.stringValue(), Var.of("cat")), "length"));
		Projection root = new Projection(length, new ProjectionElemList(new ProjectionElem("length")));
		assertThat(NativeAggregateDemandAnalysis.analyze(root).demand(definition))
				.isEqualTo(NativeAggregateResultDemand.LEXICAL_LENGTH);
		root.getProjectionElemList().addElement(new ProjectionElem("cat"));
		assertThat(NativeAggregateDemandAnalysis.analyze(root).demand(definition))
				.isEqualTo(NativeAggregateResultDemand.FULL_VALUE);
	}

	@Test
	void unevaluatedPlaceholderDoesNotDonatePatternPositions() {
		Group group = new Group(new SingletonSet());
		group.addGroupElement(new GroupElem("total", new Count(new ValueConstant(VF.createLiteral(99)))));
		Count placeholder = new Count(new Exists(new StatementPattern(Var.of("unreadSubject"),
				Var.of("unreadPredicate"), Var.of("unreadObject"))));
		Extension root = new Extension(group, new ExtensionElem(placeholder, "total"));
		assertThat(NativeValuePositionAnalysis.analyze(root).masksFor(root))
				.doesNotContainKeys("unreadSubject", "unreadPredicate", "unreadObject");
	}

	private static LmdbNativeAggregatePlanner planner() {
		return new LmdbNativeAggregatePlanner(context(), mock(LmdbNativeEvaluationStrategy.class),
				mock(NativeLmdbQuerySource.class));
	}

	private static QueryEvaluationContext context() {
		return new QueryEvaluationContext.Minimal((Dataset) null);
	}
}
